import React, { PureComponent } from 'react'
import {
  Row,
  message,
  Upload,
  Icon,
  Col,
  Alert,
  Select,
  Button,
  Form,
  Input
} from 'antd'
import { connect } from 'react-redux'
import LayoutContent from '../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../components/utility/layoutWrapper'
import ProfileWrapperStyled from './index.style'
import translationsActions from '../../redux/translations/actions'

const { getTranslations, postTranslations, postTranslationsEntry } = translationsActions

const Dragger = Upload.Dragger
const Option = Select.Option
const TextArea = Input.TextArea

class TranslationsPage extends PureComponent {
  constructor (props) {
    super(props)
    this.state = {
    }
  }

  componentDidMount () {
  }

  customRequest = ({ file }) => {
    const { selectedLanguage } = this.state
    const { type } = file
    if (type === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet') {
      const formData = new FormData()
      formData.append('file', file)
      this.props.postTranslations({ body: formData, params: { target: selectedLanguage } })
    } else {
      message.error('Incorrect file type, please upload only .xlsx')
    }
  }

  handleSubmit = (e) => {
    e.preventDefault()
    this.props.form.validateFields((err, values) => {
      if (!err) {
        this.props.postTranslationsEntry({ body: values })
      }
    })
  }

  handleSelect (val) {
    this.setState({
      selectedLanguage: val
    })
  }

  render () {
    const templateList = [
      // {name: 'Indonesia', code: 'ind'},
      { name: 'Vietnam', code: 'vie' },
      // {name: 'English', code: 'eng'},
      { name: 'Thailand', code: 'tha' }
    ]
    const {
      getFieldDecorator
    } = this.props.form
    const {
      loadingGetTranslations,
      errorGetTranslations,
      loadingPostTranslations,
      errorPostTranslations,
      getTranslationsStatus,
      postTranslationsStatus,
      postTranslationEntryLoading,
      postTranslationEntryError,
      postTranslationsEntryStatus
    } = this.props
    const {
      selectedLanguage
    } = this.state
    return (
      <ProfileWrapperStyled>
        <LayoutContentWrapper>
          <LayoutContent className='layout-content'>
            <Row>
              <Col xs={{ span: 24 }} lg={{ span: 12 }}>
                <Form
                  layout='inline'
                  onSubmit={this.handleSubmit}
                  label='Create new entry'
                >
                  <Form.Item>
                    {getFieldDecorator('master_string', {
                      rules: [{ required: true, message: 'Please input source text!' }]
                    })(
                      <TextArea
                        autosize={{ minRows: 2, maxRows: 8 }}
                        placeholder='Source text'
                      />
                    )}
                  </Form.Item>
                  <Form.Item>
                    {getFieldDecorator('translation_string', {
                      rules: [{ required: true, message: 'Please input your translated text!' }]
                    })(
                      <TextArea
                        autosize={{ minRows: 2, maxRows: 8 }}
                        placeholder='Translated text'
                      />
                    )}
                  </Form.Item>
                  <Form.Item>
                    <Button
                      type='primary'
                      htmlType='submit'
                    >
                      Submit
                    </Button>
                  </Form.Item>
                </Form>
              </Col>
              <Col xs={{ span: 24 }} lg={{ span: 6 }}>
                <Select
                  showSearch
                  style={{ width: '100%' }}
                  placeholder='Select a language'
                  onSelect={val => this.handleSelect(val)}
                >
                  {
                    templateList.map(({ code, name }) => (
                      <Option key={code} value={code}>{name}</Option>
                    ))
                  }
                </Select>
              </Col>
              <Col xs={{ span: 24 }} lg={{ span: 6 }}>
                <Button
                  style={{ width: '100%' }}
                  disabled={!selectedLanguage}
                  onClick={() => this.props.getTranslations({ params: { target: selectedLanguage } })}
                >
                  Download Translations
                </Button>
              </Col>
            </Row>
            <Row style={{ marginTop: '10px' }}>
              {
                !postTranslationEntryLoading && postTranslationsEntryStatus && (
                  <Alert
                    style={{ marginBottom: '10px', textAlign: 'center' }}
                    message={postTranslationEntryError ? 'Failed posting translations entry' : 'Success posting translations entry'}
                    type={postTranslationEntryError ? 'error' : 'success'} />
                )
              }
              {
                !loadingPostTranslations && postTranslationsStatus && (
                  <Alert
                    style={{ marginBottom: '10px', textAlign: 'center' }}
                    message={errorPostTranslations ? 'Failed, please re-upload the file' : 'Your data was successfully uploaded'}
                    type={errorPostTranslations ? 'error' : 'success'} />
                )
              }
              {
                !loadingGetTranslations && getTranslationsStatus && (
                  <Alert
                    style={{ marginBottom: '10px', textAlign: 'center' }}
                    message={errorGetTranslations ? 'Failed downloading translations' : 'Success downloading translations'}
                    type={errorGetTranslations ? 'error' : 'success'} />
                )
              }
              <Dragger
                disabled={loadingPostTranslations || !selectedLanguage}
                name='file'
                showUploadList={false}
                multiple={false}
                customRequest={val => this.customRequest(val)}
              >
                {(!selectedLanguage) ? (
                  <div>
                    <p className='ant-upload-drag-icon'>
                      <Icon type='info-circle' />
                    </p>
                    <p className='ant-upload-text'>Select a language to upload</p>
                  </div>
                ) : (
                  <div>
                    <p className='ant-upload-drag-icon'>
                      <Icon type='inbox' />
                    </p>
                    <p className='ant-upload-text'>Click or drag file to this area to upload</p>
                  </div>
                )}
              </Dragger>
            </Row>
            <iframe title='Data Studio' width='100%' height='400' src='https://datastudio.google.com/embed/reporting/4584b82d-5738-4234-82f3-ca07d9ee3759/page/2ifhB' />
          </LayoutContent>
        </LayoutContentWrapper>
      </ProfileWrapperStyled>
    )
  }
}

TranslationsPage.propTypes = {
  //   profileData: PropTypes.object.isRequired
}

TranslationsPage.defaultProps = {
  //   profileData: {}
}

const WrappedTranslationsPage = Form.create()(TranslationsPage)

export default connect(
  state => ({
    postTranslationsStatus: state.Translations.postTranslationsStatus,
    getTranslationsStatus: state.Translations.getTranslationsStatus,
    postTranslationsEntryStatus: state.Translations.postTranslationsEntryStatus,
    loadingGetTranslations: state.Loading.GET_TRANSLATIONS,
    errorGetTranslations: state.Error.GET_TRANSLATIONS,
    loadingPostTranslations: state.Loading.POST_TRANSLATIONS,
    errorPostTranslations: state.Error.POST_TRANSLATIONS,
    postTranslationEntryLoading: state.Loading.POST_TRANSLATIONS_ENTRY,
    postTranslationEntryError: state.Error.POST_TRANSLATIONS_ENTRY
  }),
  {
    getTranslations,
    postTranslations,
    postTranslationsEntry
  }
)(WrappedTranslationsPage)
